{
  "title": "古村落迷雾",
  "scene": "天色渐晚，古村落中弥漫着神秘的气息。李明和小伙伴们在一片古树前发现一块破旧的木牌子，上面刻着一行模糊的字：‘黑夜中的光明’。木牌子看起来有些松动，轻轻一推便晃动了一下。不远处的古井旁，有一块石碑，上面刻着一些不规则的符号。孩子们开始猜测这些符号的意义。",
  "goal": "找到通往村落深处的秘密入口。",
  "clue": "古树下的木牌子松动，古井旁的石碑上有符号。",
  "choices": [
    {"id": "A", "text": "查看木牌子的背面", "outcome": "木牌子背面松动，轻轻一推便露出一个暗格，里面有一张纸条，上面写着：‘黑夜中寻找光明之烛’。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "尝试解读石碑上的符号", "outcome": "经过仔细观察，李明发现石碑上的符号和木牌子上的字有相似之处，猜测两者可能有关联。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "询问周围的老人", "outcome": "村里的老人虽然没有直接提供线索，但提到：‘黑夜中的光明’可能指的是村里的灯会，每年这个时候都会点亮许多灯笼。', "result": "success", "next": "next_level"}
  ]
}
